parameters.jsCode:
const body = $input.item.json.body || $input.item.json;
const company_id = Number(body.company_id);
const modo = (body.modo === 'outreach') ? 'outreach' : 'blog';
if (!company_id) {
  return [{ json: { error: true, motivo: 'Falta company_id en el body del webhook.' } }];
}
// Tope por corrida (28-oct): 10 por defecto, de 1 a 20 — cuida la reputación del correo de la empresa
// y entra en un solo pedido a la IA.
const limite = Math.min(20, Math.max(1, parseInt(body.limite, 10) || 10));
// dry_run: arma los correos y los devuelve, sin crear borradores ni tocar el CRM.
const dry_run = body.dry_run === true;
return [{ json: { company_id, modo, limite, dry_run, error: false } }];

const params = $('🔧 Extraer Parámetros').first().json;
// Quién recibe correo lo decide 🔍 Seleccionar Contactos (28-oct); acá solo se arman.
const sel = $('🔍 Seleccionar Contactos').first().json;
if (sel.sinLeads) return [{ json: { sinLeads: true, motivo: sel.motivo } }];
const modo = params.modo;
const G54_BASE_URL = 'https://apigrowth.mdarthurdigital.com';
const G54_AGENT_TOKEN = 'REDACTED_G54_AGENT_TOKEN';

let empresa = {};
try { empresa = $('📊 Obtener Empresa').first().json.data || {}; } catch (e) {}
const empresaNombre = empresa.name || 'Nuestra empresa';
const empresaWeb = empresa.website || '';
const empresaProp = (empresa.value_proposition || '').trim().replace(/\.+$/, '');
const empresaServicios = (empresa.products_services || '').split(',').map(s => s.trim()).filter(Boolean);
const empresaCobertura = (empresa.coverage || empresa.geography || '').trim().replace(/\.+$/, '');

// Blog: post más reciente (solo si modo === 'blog')
let post = null;
if (modo === 'blog') {
  try {
    const cms = $('🔗 Obtener CMS WordPress').first().json.data;
    if (!cms || !cms.is_active) {
      return [{ json: { sinLeads: true, motivo: 'La empresa no tiene WordPress conectado (Ajustes → CMS Integrations) — no hay ningún blog real que compartir.' } }];
    }
    const first = $('📰 WP: Obtener Posts').first().json;
    if (!first) {
      return [{ json: { sinLeads: true, motivo: 'El blog de la empresa no tiene ningún post publicado todavía.' } }];
    }
    const media = first._embedded && first._embedded['wp:featuredmedia'] && first._embedded['wp:featuredmedia'][0];
    post = {
      id: first.id,
      titulo: (first.title && first.title.rendered) || '',
      extracto: ((first.excerpt && first.excerpt.rendered) || '').replace(/<[^>]+>/g, '').trim(),
      url: first.link,
      imagen: media ? ((media.media_details && media.media_details.sizes && media.media_details.sizes.large && media.media_details.sizes.large.source_url) || media.source_url) : '',
    };
  } catch (e) {
    return [{ json: { sinLeads: true, motivo: 'No se pudo leer el blog real de la empresa (' + (e.message || e) + ').' } }];
  }
}

// Outreach: imagen real de una publicación reciente de RRSS, como reemplazo visual mientras
// G54 no tiene ningún campo de logo por empresa -- nunca se inventa un logo ni una imagen falsa.
let heroImagen = '';
if (modo === 'outreach') {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: G54_BASE_URL + '/api/n8n/companies/' + params.company_id + '/rrss/posts',
      headers: { Authorization: 'Bearer ' + G54_AGENT_TOKEN },
      json: true,
    });
    const conImagen = (resp.data || []).find(p => p.imagen_url);
    if (conImagen) heroImagen = conImagen.imagen_url;
  } catch (e) {
    // sin imagen real disponible -- el correo sale igual, solo sin la miniatura
  }
}

const candidatos = sel.candidatos || [];

// Correos en frío redactados por la IA con el perfil de la empresa (28-oct)
const redactados = {};
if (modo === 'outreach') {
  try {
    const j = JSON.parse($input.first().json.choices[0].message.content);
    for (const x of (j.correos || [])) if (x && x.deal_id != null) redactados[String(x.deal_id)] = x;
  } catch (e) {}
}
const limpio = (t) => String(t || '').replace(/<[^>]*>/g, '').replace(/https?:\/\/\S+/g, '').replace(/\s+/g, ' ').trim();
const validar = (x) => {
  if (!x) return null;
  const idioma = x.idioma === 'en' ? 'en' : 'es';
  const asunto = limpio(x.asunto), titulo = limpio(x.titulo), boton = limpio(x.boton);
  const parrafos = (Array.isArray(x.parrafos) ? x.parrafos : []).map(limpio).filter(Boolean);
  const servicios = (Array.isArray(x.servicios) ? x.servicios : []).map(limpio).filter(s => s && s.length <= 60).slice(0, 4);
  const palabras = parrafos.join(' ').split(' ').length;
  if (asunto.length < 5 || asunto.length > 90 || !titulo || titulo.length > 60 || parrafos.length < 2 || parrafos.length > 4 || palabras < 30 || palabras > 180) return null;
  const may = (t) => t.charAt(0).toUpperCase() + t.slice(1); // por si la IA escribe todo en minúscula
  return { idioma, asunto: may(asunto), titulo: may(titulo), parrafos: parrafos.map(may), servicios: servicios.map(may), boton: boton && boton.length <= 40 ? may(boton) : '' };
};
// Idioma de respaldo, si la IA no respondió: por el teléfono o el lugar del prospecto
const idiomaDe = (f) => {
  const tel = String((f && f.telefono) || '').replace(/[^+\d]/g, '');
  const lugar = String((f && f.lugar) || '');
  if (/puerto rico|quebec|qu\u00e9bec/i.test(lugar) || /^\+1(787|939)/.test(tel)) return 'es';
  if (/^\+1\d{10}$/.test(tel) || /\b(USA|United States|EE\.? ?UU\.?|[A-Z]{2}\s*\d{5}|, (FL|NY|TX|CA|GA|NJ|IL|ON|BC|AB))\b/.test(lugar)) return 'en';
  return 'es';
};

// Las notas del CRM admiten 1000 caracteres: si se pasan, se acorta el texto descriptivo,
// nunca las marcas (no_contactar_email, outreach_borrador, blog:N), que son las que evitan repetir.
const notasCon = (notasViejas, marca) => {
  const t = (notasViejas ? notasViejas + ' | ' : '') + marca;
  if (t.length <= 1000) return t;
  const re = /(no_contactar_email[^|]*|outreach_borrador \S+|blog:\d+)/g;
  const marcas = Array.from(new Set((notasViejas.match(re) || []).map(s => s.trim())));
  const resto = notasViejas.replace(/(no_contactar_email[^|]*|outreach_borrador \S+|blog:\d+[^|]*)/g, '').replace(/(\s*\|\s*)+/g, ' | ').replace(/^\s*\|\s*|\s*\|\s*$/g, '').trim();
  const fijo = [...marcas, marca].join(' | ');
  const lugar = Math.max(0, 1000 - fijo.length - 3);
  return ((resto.slice(0, lugar) + ' | ') + fijo).slice(-1000);
};

// --- Diseño real de G54, mismo patrón ya en producción (Marco -- correo de Lead Caliente) ---
// Logo real de la empresa (G54, campo logo_url): va solo en el pie (pedido de la usuaria, 26-oct).
// La cabecera lleva siempre la marca Growth54ai.
const logoUrl = String(empresa.logo_url || '').trim();
const marcaCeldas =
  '<td style="vertical-align:middle;"><span style="font-size:20px;font-weight:600;color:#fff;letter-spacing:-0.3px;font-family:Arial,sans-serif;">Growth</span></td>' +
  '<td style="vertical-align:middle;padding:0 1px;"><div style="width:25px;height:25px;background:#fff;border-radius:50%;text-align:center;line-height:25px;color:#2D5BFF;font-size:18px;font-weight:800;letter-spacing:-0.8px;font-family:Arial,sans-serif;display:inline-block;">54</div></td>' +
  '<td style="vertical-align:middle;"><span style="font-size:20px;font-weight:600;color:#fff;letter-spacing:-0.3px;font-family:Arial,sans-serif;">ai</span></td>';

const cabecera = (eyebrow, titulo) =>
  '<td style="background:linear-gradient(135deg,#2D5BFF 0%,#1E45D6 100%);padding:26px 28px 24px;">' +
  '<table cellpadding="0" cellspacing="0"><tr>' +
  marcaCeldas +
  '</tr></table>' +
  '<div style="margin-top:18px;font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#CFE0FF;font-weight:700;font-family:Arial,sans-serif;">' + eyebrow + '</div>' +
  '<div style="font-size:20px;font-weight:600;color:#fff;margin-top:4px;font-family:Arial,sans-serif;">' + titulo + '</div>' +
  '</td>';

const boton = (texto, url) =>
  '<tr><td style="padding:8px 28px 24px;"><table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="background:#2D5BFF;border-radius:8px;"><a href="' + url + '" style="display:block;padding:14px 20px;font-size:14.5px;font-weight:700;color:#ffffff;text-decoration:none;font-family:Arial,sans-serif;">' + texto + '</a></td></tr></table></td></tr>';

// Pie con los datos reales de la empresa (26-oct), todo desde G54: lo que no esté cargado no aparece.
// Dirección física y forma de darse de baja: las pide la ley de EE. UU. (CAN-SPAM) en correos comerciales.
const esc = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const aLista = (v) => (Array.isArray(v) ? v : String(v || '').split(/[\n,;]+/)).map(x => String(x).trim()).filter(Boolean);
const empTel = aLista(empresa.phones)[0] || '';
const empMail = aLista(empresa.emails)[0] || '';
const empDir = String(empresa.address || '').trim();
const empHorario = String(empresa.business_hours || '').trim();
const webVisible = empresaWeb.replace(/^https?:\/\//, '').replace(/\/$/, '');
const lnk = 'color:#2D5BFF;text-decoration:none;';
// HMAC-SHA256 en JavaScript puro (n8n no permite require('crypto')). Entradas en ASCII.
const sha256 = (bytes) => {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const m = bytes.slice(); const l = m.length * 8; m.push(0x80); while (m.length % 64 !== 56) m.push(0);
  for (let i = 7; i >= 0; i--) m.push(i > 3 ? 0 : (l >>> (i * 8)) & 255);
  const r = (x, n) => (x >>> n) | (x << (32 - n)); const w = new Array(64);
  for (let o = 0; o < m.length; o += 64) {
    for (let i = 0; i < 16; i++) w[i] = (m[o + 4 * i] << 24) | (m[o + 4 * i + 1] << 16) | (m[o + 4 * i + 2] << 8) | m[o + 4 * i + 3];
    for (let i = 16; i < 64; i++) { const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10); w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0; }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) { const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0, t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0; h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0; }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0; H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = []; for (const x of H) out.push((x >>> 24) & 255, (x >>> 16) & 255, (x >>> 8) & 255, x & 255); return out;
};
const firmaBaja = (secreto, texto) => {
  const bytes = (s) => Array.from(String(s), ch => ch.charCodeAt(0) & 255);
  let k = bytes(secreto); if (k.length > 64) k = sha256(k); while (k.length < 64) k.push(0);
  const interno = sha256(k.map(x => x ^ 0x36).concat(bytes(texto)));
  return sha256(k.map(x => x ^ 0x5c).concat(interno)).map(x => x.toString(16).padStart(2, '0')).join('').slice(0, 20);
};
// Enlace de baja firmado (26-oct): lo atiende el flujo ✉️ Camila — Baja de correos, que marca el trato con
// no_contactar_email; los tratos marcados se saltean arriba. La firma impide dar de baja a otro cambiando el número.
const SECRETO_BAJA = 'REDACTED_CAMILA_BAJA_SECRET';
// La firma cubre solo empresa:trato; l=en solo cambia el idioma de la página de baja.
const urlBaja = (dealId, idioma) => 'https://n8n.mdarthurdigital.com/webhook/baja-correo-g54?c=' + params.company_id + '&d=' + dealId + '&t=' + firmaBaja(SECRETO_BAJA, params.company_id + ':' + dealId) + (idioma === 'en' ? '&l=en' : '');
const PIE = {
  es: { baja: 'Si no quieres recibir más correos de ' + empresaNombre + ', puedes darte de baja', aqui: 'aquí', horario: 'Horario' },
  en: { baja: 'If you would rather not receive more emails from ' + empresaNombre + ', you can unsubscribe', aqui: 'here', horario: 'Hours' },
};
const footer = (dealId, idioma = 'es') => {
  const P = PIE[idioma] || PIE.es;
  const contacto = [
    empTel ? '<a href="tel:' + empTel.replace(/[^+\d]/g, '') + '" style="' + lnk + '">' + esc(empTel) + '</a>' : '',
    empMail ? '<a href="mailto:' + esc(empMail) + '" style="' + lnk + '">' + esc(empMail) + '</a>' : '',
    empresaWeb ? '<a href="' + esc(empresaWeb) + '" style="' + lnk + '">' + esc(webVisible) + '</a>' : '',
  ].filter(Boolean).join(' &nbsp;·&nbsp; ');
  const marca = logoUrl
    ? '<img src="' + esc(logoUrl) + '" alt="' + esc(empresaNombre) + '" style="height:26px;max-width:130px;display:block;margin-bottom:8px;" />'
    : '<div style="font-size:13px;font-weight:700;color:#111827;margin-bottom:6px;">' + esc(empresaNombre) + '</div>';
  return '<tr><td style="padding:20px 28px 22px;background:#f9fafb;border-top:1px solid #e5e7eb;font-family:Arial,sans-serif;">' +
    marca +
    (empDir ? '<div style="font-size:12px;color:#4b5563;line-height:1.5;">' + esc(empDir) + '</div>' : '') +
    (contacto ? '<div style="font-size:12px;color:#4b5563;line-height:1.6;margin-top:4px;">' + contacto + '</div>' : '') +
    (empHorario ? '<div style="font-size:12px;color:#6b7280;margin-top:4px;">' + P.horario + ': ' + esc(empHorario) + '</div>' : '') +
    '<div style="font-size:10.5px;color:#9ca3af;line-height:1.5;margin-top:12px;">' + esc(P.baja) + ' <a href="' + urlBaja(dealId, idioma) + '" style="color:#6b7280;text-decoration:underline;">' + P.aqui + '</a>.</div>' +
    '</td></tr>';
};
const footerTexto = (dealId, idioma = 'es') => { const P = PIE[idioma] || PIE.es; return ['--', empresaNombre, empDir, [empTel, empMail, empresaWeb].filter(Boolean).join(' · '),
  empHorario ? P.horario + ': ' + empHorario : ''].filter(Boolean).join('\n') + '\n\n' + P.baja + ': ' + urlBaja(dealId, idioma); };

const parrafo = (texto) =>
  '<tr><td style="padding:8px 28px 4px;"><span style="font-size:14px;color:#374151;font-family:Arial,sans-serif;line-height:1.6;">' + texto + '</span></td></tr>';

const listaServicios = (items) => {
  if (!items.length) return '';
  const filas = items.slice(0, 5).map(s =>
    '<tr><td style="padding:4px 0;vertical-align:top;width:18px;font-size:14px;color:#2D5BFF;">✓</td><td style="padding:4px 0;font-size:14px;color:#111827;font-family:Arial,sans-serif;font-weight:600;">' + s + '</td></tr>'
  ).join('');
  return '<tr><td style="padding:12px 28px 4px;"><table width="100%" cellpadding="0" cellspacing="0">' + filas + '</table></td></tr>';
};

const imagenRow = (url) => url ? '<tr><td style="padding:14px 28px 4px;"><img src="' + url + '" alt="" style="width:100%;max-width:464px;border-radius:8px;display:block;" /></td></tr>' : '';

const wrap = (bodyRows) =>
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="text-align:center;">' +
  '<table width="520" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;overflow:hidden;width:520px;margin:0 auto;font-family:Arial,Helvetica,sans-serif;">' +
  bodyRows +
  '</table></td></tr></table>';

// Armar el email por cada lead (personalizado)
const salida = candidatos.map(d => {
  let asunto, html, texto, notaNueva, conIa = false, idiomaCorreo = 'es';

  if (modo === 'outreach') {
    const negocio = d.nombre || '';
    const f = d.ficha || {};
    const ia = validar(redactados[String(d.id)]);
    let idioma, titulo, parrafos, servicios, textoBoton;
    if (ia) {
      ({ idioma, asunto, titulo, parrafos, servicios } = ia);
      textoBoton = ia.boton || (idioma === 'en' ? 'Visit ' + empresaNombre : 'Conocer ' + empresaNombre);
    } else {
      idioma = idiomaDe(f);
      const rubro = f.categoria || f.buscado_como;
      if (idioma === 'en') {
        asunto = (empresaNombre + ' for ' + (negocio || 'your business')).slice(0, 60);
        titulo = 'Hello' + (negocio ? ', ' + negocio : '');
        parrafos = [
          'We came across ' + (negocio || 'your business') + (f.lugar ? ' in ' + f.lugar : '') + ' and think what we do at ' + empresaNombre + ' could be useful to you.',
          'If it sounds interesting, just reply to this email and we will tell you more.',
        ];
        servicios = []; // los nombres del perfil pueden estar en otro idioma
        textoBoton = 'Visit ' + empresaNombre;
      } else {
        asunto = (empresaNombre + ' para ' + (negocio || 'tu negocio')).slice(0, 60);
        titulo = 'Hola' + (negocio ? ', ' + negocio : '');
        parrafos = [
          'Encontramos ' + (negocio || 'su negocio') + (rubro ? ' (' + rubro + ')' : '') + (f.lugar ? ' en ' + f.lugar : '') + ' y creemos que lo que hacemos en ' + empresaNombre + ' puede serles útil.',
          'Somos ' + empresaNombre + (empresaProp ? ': ' + empresaProp : '') + '.' + (empresaCobertura ? ' Trabajamos en ' + empresaCobertura + '.' : ''),
          'Si les interesa, respondan este correo y les contamos más.',
        ];
        servicios = empresaServicios.slice(0, 4);
        textoBoton = 'Conocer ' + empresaNombre;
      }
    }
    conIa = !!ia;
    idiomaCorreo = idioma;
    html = wrap(
      '<tr>' + cabecera(esc(empresaNombre) + (idioma === 'en' ? ' · Contact' : ' · Contacto'), esc(titulo)) + '</tr>' +
      parrafos.map(p => parrafo(esc(p))).join('') +
      listaServicios(servicios.map(esc)) +
      imagenRow(heroImagen) +
      boton(esc(textoBoton) + ' →', empresaWeb || '#') +
      footer(d.id, idioma)
    );
    texto = parrafos.join('\n\n') + (servicios.length ? '\n\n' + servicios.map(s => '- ' + s).join('\n') : '') + (empresaWeb ? '\n\n' + empresaWeb : '') + '\n\n' + footerTexto(d.id, idioma);
    notaNueva = notasCon(d.notas || '', 'outreach_borrador ' + new Date().toISOString().slice(0,10));
  } else {
    const nombre = (d.nombre || '').split(' ')[0] || 'hola';
    asunto = post.titulo ? `${empresaNombre} — ${post.titulo}` : `Novedades de ${empresaNombre}`;
    const saludo = '<tr><td style="padding:24px 28px 4px;"><span style="font-size:14.5px;color:#374151;font-family:Arial,sans-serif;">Hola ' + nombre + ',</span></td></tr>';
    const tituloPost = '<tr><td style="padding:8px 28px 4px;"><span style="font-size:18px;font-weight:700;color:#111827;font-family:Arial,sans-serif;">' + post.titulo + '</span></td></tr>';
    const extractoRow = '<tr><td style="padding:12px 28px 4px;"><span style="font-size:14px;color:#374151;font-family:Arial,sans-serif;line-height:1.5;">' + post.extracto + '</span></td></tr>';
    html = wrap(
      '<tr>' + cabecera(empresaNombre + ' · Notas del blog', 'Nueva publicación') + '</tr>' +
      saludo + tituloPost + imagenRow(post.imagen) + extractoRow +
      boton('Leer la nota completa →', post.url) +
      footer(d.id)
    );
    texto = `${post.titulo}\n\n${post.extracto}\n\nLeer más: ${post.url}\n\n${footerTexto(d.id)}`;
    notaNueva = notasCon(d.notas || '', 'blog:' + post.id + ' en revisión ' + new Date().toISOString().slice(0,10));
  }

  return {
    json: {
      deal_id: d.id,
      email: d.email,
      nombre: d.nombre || null,
