    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) { const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0, t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0; h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0; }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0; H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = []; for (const x of H) out.push((x >>> 24) & 255, (x >>> 16) & 255, (x >>> 8) & 255, x & 255); return out;
};
const firmaBaja = (secreto, texto) => {
  const bytes = (s) => Array.from(String(s), ch => ch.charCodeAt(0) & 255);
  let k = bytes(secreto); if (k.length > 64) k = sha256(k); while (k.length < 64) k.push(0);
  const interno = sha256(k.map(x => x ^ 0x36).concat(bytes(texto)));
  return sha256(k.map(x => x ^ 0x5c).concat(interno)).map(x => x.toString(16).padStart(2, '0')).join('').slice(0, 20);
};
